-- 5. Insert Production Tracking initial records
SELECT id, status, assigned_employee_id, order_date,
  CASE WHEN status = 'DELIVERY' THEN 'COMPLETED' WHEN status = 'READY_TO_DELIVERY' THEN 'COMPLETED' ELSE 'IN_PROGRESS' END,
  order_date
FROM customer_orders;

-- 6. Insert Order Measurements for every order
SELECT id, garment_type,
  CASE WHEN garment_type = 'BLOUSE' THEN '{"L":"14.5","SH":"14","AH":"16.5","SL":"6.5","SL.O":"11","BN":"8.5","FN":"6.5","DP-1":"9.5","DP-2":"11","B-1":"34","B-2":"36","B-3":"30","F.HOOK":"Yes","B.HOOK":"No","LINING":"Cotton","AV.":"Normal","SARI":"Falls"}'
  ELSE '{"F.N.":"6","B.N.":"6.5","H.B.":"34","L":"42","S.S.":"18","S.L.":"15","S.LO":"10.5","AM":"13","B":"36","H":"38","T.S.":"21","P.L.":"38","S.":"24","L.":"12","S.CUT":"Straight","LNG":"Full","SHALL":"Matching","B.D.":"Chudi"}'
  END,
  order_date
FROM customer_orders;

-- 7. Sync Customer Total Orders count
UPDATE customers c
SET total_orders = (SELECT COUNT(*) FROM customer_orders o WHERE o.customer_mobile = c.customer_mobile);



-- 8. Populate Customer Sizing Profiles directly linked to Mobile Number (Clean, no lining, no order sync)
    customer_mobile,
    customer_name,
    garment_type,
    lining,
    measurements_json,
    notes,
    created_at,
    updated_at
)
SELECT
    c.customer_mobile,
    c.customer_name,
    om.garment_type,
    NULL,
    om.measurements_json,
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM order_measurements om
JOIN customer_orders o ON om.order_id = o.id
JOIN customers c ON o.customer_mobile = c.customer_mobile
WHERE om.id IN (
    SELECT MAX(om2.id)
    FROM order_measurements om2
    JOIN customer_orders o2 ON om2.order_id = o2.id
    WHERE om2.garment_type IS NOT NULL AND om2.garment_type != ''
    GROUP BY o2.customer_mobile, om2.garment_type
);